// Message Normalizer & Input Validator
const item = $input.first().json;
const body = item.body || item;

const allowedSources = ['GMAIL', 'TELEGRAM', 'CALENDAR', 'DOCUMENT', 'MANUAL'];

const source = (body.source || 'MANUAL').toUpperCase();
const content = body.content ? body.content.trim() : '';

if (!content || content.length < 3) {
  return [{
    json: {
      success: false,
      processed: false,
      created: false,
      message: 'Invalid message payload: missing or empty content'
    }
  }];
}

if (!allowedSources.includes(source)) {
  return [{
    json: {
      success: false,
      processed: false,
      created: false,
      message: `Invalid message payload: source must be one of ${allowedSources.join(', ')}`
    }
  }];
}

// Generate normalized message ID (externalId or fallback hash)
const externalId = body.externalId || null;
const sender = body.sender || null;
const subject = body.subject || null;
const timestamp = body.timestamp || new Date().toISOString();
const metadata = body.metadata || {};

return [{
  json: {
    isValid: true,
    normalizedMessage: {
      source,
      externalId,
      sender,
      subject,
      content,
      timestamp,
      metadata
    }
  }
}];

