// Format Non-Obligation Result
return [{
  json: {
    success: true,
    processed: false,
    created: false,
    message: 'No actionable obligation detected',
    reason: $input.first().json.data?.reason || 'No actionable obligation detected'
  }
}];

// Format Creation Response (handles Created vs Duplicate)
const backendRes = $input.first().json;

if (backendRes.duplicate) {
  return [{
    json: {
      success: true,
      processed: true,
      created: false,
      duplicate: true,
      message: 'Duplicate obligation detected',
      obligation: backendRes.data
    }
  }];
}

return [{
  json: {
    success: true,
    processed: true,
    created: true,
    duplicate: false,
    message: 'Obligation created successfully',
    obligation: backendRes.data
  }
}];
